package fraymus.workspace;
import org.json.*;
import org.junit.Test;
import java.nio.file.*;
import static org.junit.Assert.*;

public class PhysicalAudit130Test {
 private JSONObject view(){var rows=new JSONArray();for(int i=1;i<=20;i++)rows.put(new JSONObject().put("ordinal",i).put("bodyId","b").put("seconds",i*.1).put("accepted",i!=10).put("positionM",new JSONArray(new double[]{i*.1,0})).put("radiusM",.1).put("status",i==10?"prediction-only":"measured-estimate"));return new JSONObject().put("rows",rows);}
 private JSONObject refs(){return new JSONObject().put("source","Analytic later references, not a physical study").put("references",new JSONArray().put(new JSONObject().put("ordinal",5).put("bodyId","b").put("positionM",new JSONArray("[.65,0]"))).put(new JSONObject().put("ordinal",10).put("bodyId","b").put("positionM",new JSONArray("[1,0]"))));}
 @Test public void rejectedMeasurementsStayMissingAndAllowanceIsSeparate(){var audit=PhysicalAudit130.compute(view(),refs().put("referenceRadiusM",.1));var m=audit.getJSONObject("measurement");assertEquals(2,m.getInt("references"));assertEquals(1,m.getInt("available"));assertEquals(1,m.getInt("missing"));assertEquals(0,m.getInt("coveredCentre"));assertEquals(1,m.getInt("coveredIncludingReferenceRadius"));assertEquals(.15,m.getDouble("meanErrorM"),1e-12);assertEquals(.1,m.getDouble("meanRadiusM"),0);}
 @Test public void referencesOnlyScoreAndNeverRewritePredictions(){var v=view();var before=v.toString();var a=PhysicalAudit130.compute(v,refs());var changed=refs();changed.getJSONArray("references").getJSONObject(0).put("positionM",new JSONArray("[20,30]"));var b=PhysicalAudit130.compute(v,changed);assertEquals(before,v.toString());for(String policy:a.getJSONObject("forecastScores").keySet()){var x=a.getJSONObject("forecastScores").getJSONArray(policy);var y=b.getJSONObject("forecastScores").getJSONArray(policy);assertEquals(x.getJSONObject(0).getDouble("radiusM"),y.getJSONObject(0).getDouble("radiusM"),0);assertTrue(y.getJSONObject(0).getDouble("errorM")>30);}}
 @Test public void seedDuplicateUnknownAndNonfiniteReferencesRefuse(){var r=refs();r.getJSONArray("references").getJSONObject(0).put("ordinal",0);assertThrows(IllegalArgumentException.class,()->PhysicalAudit130.compute(view(),r));r.getJSONArray("references").getJSONObject(0).put("ordinal",10);assertThrows(IllegalArgumentException.class,()->PhysicalAudit130.compute(view(),r));r.getJSONArray("references").getJSONObject(0).put("ordinal",21);assertThrows(IllegalArgumentException.class,()->PhysicalAudit130.compute(view(),r));assertThrows(IllegalArgumentException.class,()->PhysicalAudit130.compute(view(),refs().put("referenceRadiusM",-.1)));}
 @Test public void savedAuditRechecksOriginalSourcesAcrossRestartAndRejectsTampering()throws Exception{
  var root=Files.createTempDirectory("physical130");var ledger=new WorldLedger(root);String world=ledger.create(WorldLedgerTest.source(WorldLedgerTest.suite().getJSONArray("cases").getJSONObject(0)),"130 audit").getString("id");
  try(var observations=new WorldObservationStore(root,ledger)){var metric=new MetricObservationStore(root,observations,ledger);var pack=WorldObservationStoreTest.pack();var dataset=WorldObservationStoreTest.importPack(observations,pack);var seconds=new JSONArray();for(int i=0;i<pack.getJSONArray("frames").length();i++)seconds.put(i*.1);metric.clock(new JSONObject().put("datasetId",dataset.getString("id")).put("seconds",seconds).put("source","Synthetic control clock").put("cameraKey","test-fixed"));String geo=metric.geometry(PlaneCalibrationTest.mat().put("imagePoints",new JSONArray("[[0,0],[1,0],[1,1],[0,1]]"))).getString("id");var original=WorldObservationStoreTest.settled(observations,observations.start(WorldObservationStoreTest.arguments(ledger,world,dataset,0)).getString("id"));var selection=new JSONObject().put("runId",original.getString("id")).put("geometryId",geo);var v=metric.view(selection);var row=v.getJSONArray("rows").getJSONObject(2);var input=WorldFrames.copy(selection).put("source","Analytic fixture, not independent physical evidence").put("references",new JSONArray().put(new JSONObject().put("ordinal",row.getInt("ordinal")).put("bodyId",row.getString("bodyId")).put("positionM",new JSONArray("[.1,.1]"))));var store=new PhysicalAudit130(root,metric);var audit=store.save(input);assertTrue(audit.similar(store.save(input)));assertTrue(audit.similar(new PhysicalAudit130(root,new MetricObservationStore(root,observations,ledger)).read(audit.getString("id"))));assertTrue(original.similar(observations.read(original.getString("id"))));Path f=root.resolve("physical-audits130").resolve(audit.getString("id")+".json");String originalBytes=Files.readString(f);Files.writeString(f,originalBytes.replace("Analytic fixture","Forged fixture"));assertThrows(IllegalStateException.class,()->store.read(audit.getString("id")));Files.writeString(f,originalBytes);
   Path state=root.resolve("metric-observations/state.json");String bytes=Files.readString(state);Files.writeString(state,bytes.replace("test-fixed","changed"));assertThrows(IllegalStateException.class,()->store.read(audit.getString("id")));assertEquals(bytes.replace("test-fixed","changed"),Files.readString(state));
  }
 }
}
